import * as T36 from "three";
function makeRoad(e) {
    const root = new T36.Group(),
        p = assetParameters(e),
        m = material(e.color),
        mark = material(new T36.Color(e.color).multiplyScalar(0.45));
    const anchors = [];
    root.userData.contactAnchors = anchors;
    const b2 = (w2, h2, d, x = 0, y = h2 / 2, z = 0, mat = m) => box2(root, mat, w2, h2, d, x, y, z, 0);
    const anchor = (id, x, y, z, role = "surface") => anchors.push({ id, role, position: [x, y, z], normal: [0, 1, 0] });
    const w = p.width,
        l = p.length,
        h = p.height;
    if (e.asset === "road-curve") {
        const angle = T36.MathUtils.degToRad(p.turn),
            inner = p.radius - w / 2,
            outer = p.radius + w / 2;
        const shape = new T36.Shape();
        shape.absarc(0, 0, outer, -angle, 0, false);
        shape.absarc(0, 0, inner, 0, -angle, true);
        shape.closePath();
        const g2 = new T36.ExtrudeGeometry(shape, { depth: h, bevelEnabled: false, curveSegments: 48 });
        g2.rotateX(-Math.PI / 2);
        g2.translate(0, -h, 0);
        mesh(root, g2, m);
        for (const [id, a2] of [
            ["start", 0.01],
            ["middle", angle / 2],
            ["end", angle - 0.01],
        ])
            anchor(id, p.radius * Math.cos(a2), 0, p.radius * Math.sin(a2));
        const count = Math.max(1, Math.ceil((p.radius * angle) / 2));
        for (let i = 0; i < count; i++) {
            const a2 = ((i + 0.5) * angle) / count;
            const dash = b2(Math.min(0.09, w * 0.05), 5e-3, Math.min(0.85, ((p.radius * angle) / count) * 0.5), p.radius * Math.cos(a2), 3e-3, p.radius * Math.sin(a2), mark);
            dash.rotation.y = -a2;
        }
        anchors.forEach((a2) => {
            a2.position[0] *= (p.radius + w * 0.25) / p.radius;
            a2.position[2] *= (p.radius + w * 0.25) / p.radius;
        });
    } else if (e.asset === "road-junction") {
        const a2 = w / 2,
            c2 = l / 2;
        const outline = [
            [-a2, -c2],
            [a2, -c2],
            [a2, -a2],
            [c2, -a2],
            [c2, a2],
            [a2, a2],
            [a2, c2],
            [-a2, c2],
            [-a2, a2],
            [-c2, a2],
            [-c2, -a2],
            [-a2, -a2],
        ];
        const g2 = new T36.ExtrudeGeometry(new T36.Shape(outline.map((v) => new T36.Vector2(v[0], v[1]))), { depth: h, bevelEnabled: false });
        g2.rotateX(Math.PI / 2);
        mesh(root, g2, m);
        anchor("center", 0, 0, 0);
    } else if (e.asset === "road-busstop") {
        b2(w, 0.08, l, 0, h - 0.04);
        const post = Math.min(0.09, w * 0.05, l * 0.08);
        for (const x of [-w / 2 + post / 2, w / 2 - post / 2]) b2(post, h, post, x, h / 2, -l / 2 + post / 2);
        b2(w - post * 2, h * 0.6, post * 0.5, 0, h * 0.55, -l / 2 + post / 2);
        const seatW = w * 0.65,
            seatD = l * 0.28,
            seatH = Math.min(0.45, h * 0.25);
        b2(seatW, 0.06, seatD, 0, seatH - 0.03, -l * 0.1);
        for (const x of [-seatW * 0.4, seatW * 0.4]) b2(post, seatH - 0.06, seatD * 0.8, x, (seatH - 0.06) / 2, -l * 0.1);
        const seats = Math.max(1, Math.floor(seatW / 0.6));
        for (let i = 0; i < seats; i++) anchor("seat-" + i, ((i - (seats - 1) / 2) * seatW) / seats, seatH, -l * 0.1, "seat");
    } else {
        const top = ["road-sidewalk", "road-curb"].includes(e.asset) ? h : 0;
        b2(w, h, l, 0, top - h / 2);
        anchor("surface", w * 0.25, top, 0);
        if (e.asset === "road-straight") for (let z = -l / 2 + 0.6; z < l / 2 - 0.4; z += 2) b2(Math.min(0.1, w * 0.05), 5e-3, Math.min(1, l * 0.2), 0, 3e-3, z, mark);
        if (e.asset === "road-parking") {
            const t = Math.min(0.06, w * 0.05, l * 0.05);
            for (const x of [-w / 2 + t, w / 2 - t]) b2(t, 5e-3, l - t * 2, x, 3e-3, 0, mark);
            b2(w - t, 5e-3, t, 0, 3e-3, -l / 2 + t, mark);
        }
        if (e.asset === "road-bridge") {
            const t = Math.min(0.08, w * 0.04),
                railH = 1.1,
                count = Math.max(2, Math.ceil(l / 1.5));
            for (const x of [-w / 2 + t, w / 2 - t]) {
                b2(t, t, l, x, railH - t / 2);
                for (let i = 0; i < count; i++) b2(t, railH, t, x, railH / 2, -l / 2 + t + (i * (l - t * 2)) / (count - 1));
            }
        }
    }
    return root;
}

